import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.D5wUhsuj.js";const p=JSON.parse('{"title":"Архитектура","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md","lastUpdated":1785946763000}'),i={name:"architecture.md"};function c(r,e,l,s,h,n){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="архитектура" tabindex="-1">Архитектура <a class="header-anchor" href="#архитектура" aria-label="Permalink to &quot;Архитектура&quot;">​</a></h1><h2 id="назначение" tabindex="-1">Назначение <a class="header-anchor" href="#назначение" aria-label="Permalink to &quot;Назначение&quot;">​</a></h2><p>Gigaplan Frontend — встраиваемый виджет чата с ИИ-агентом для жилых комплексов. Пользователь общается в чате; ответы ассистента могут содержать <strong>визуальные блоки</strong> (карта, генплан, квартиры, документы и т.д.), которые открываются в соседней панели.</p><h2 id="стек" tabindex="-1">Стек <a class="header-anchor" href="#стек" aria-label="Permalink to &quot;Стек&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Технология</th><th>Роль</th></tr></thead><tbody><tr><td>Vue 3 (Composition API, <code>&lt;script setup&gt;</code>)</td><td>UI</td></tr><tr><td>Pinia</td><td>Состояние</td></tr><tr><td>Vite</td><td>Dev-сервер и lib-сборка IIFE</td></tr><tr><td>Axios</td><td>HTTP</td></tr><tr><td>Sass</td><td>Стили, design tokens</td></tr><tr><td>Swiper</td><td>Карусели</td></tr><tr><td>mitt</td><td>Легковесный event bus</td></tr><tr><td>Yandex Maps / Planoplan</td><td>Внешние виджеты в feature-модулях</td></tr></tbody></table><h2 id="точки-входа" tabindex="-1">Точки входа <a class="header-anchor" href="#точки-входа" aria-label="Permalink to &quot;Точки входа&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Файл</th><th>Роль</th></tr></thead><tbody><tr><td><code>src/main.ts</code></td><td>Dev: Pinia + <code>useInitApp</code> + mount <code>#app</code></td></tr><tr><td><code>src/entry.ts</code></td><td>Prod: <code>mountGigaplanWidget(options)</code></td></tr><tr><td><code>src/App.vue</code></td><td>Корневой layout <code>#gigaplan.gigaplan.gigaplan-mode-*</code></td></tr><tr><td><code>index.html</code></td><td>Оболочка только для dev</td></tr></tbody></table><h2 id="feature-модули" tabindex="-1">Feature-модули <a class="header-anchor" href="#feature-модули" aria-label="Permalink to &quot;Feature-модули&quot;">​</a></h2><p>Каждая папка в <code>src/features/&lt;name&gt;/</code> обычно содержит:</p><ul><li><code>views/</code> — экран, монтируемый из <code>App</code> или <code>ChatView</code>;</li><li><code>components/</code> — части экрана;</li><li><code>store/</code> — Pinia (если нужен локальный стейт);</li><li><code>types/</code> — TypeScript-контракты;</li><li>опционально <code>services/</code>, <code>composables/</code>, <code>icons/</code>, <code>utils/</code>, <code>api/</code>.</li></ul><h2 id="shared" tabindex="-1">Shared <a class="header-anchor" href="#shared" aria-label="Permalink to &quot;Shared&quot;">​</a></h2><p>Переиспользуемый UI-kit, <code>settingsStore</code>, сервисы init-проекта, утилиты, иконки. Features <strong>не</strong> должны дублировать базовые кнопки/инпуты — берут из <code>shared/components</code>.</p><h2 id="потоки-данных" tabindex="-1">Потоки данных <a class="header-anchor" href="#потоки-данных" aria-label="Permalink to &quot;Потоки данных&quot;">​</a></h2><h3 id="инициализация" tabindex="-1">Инициализация <a class="header-anchor" href="#инициализация" aria-label="Permalink to &quot;Инициализация&quot;">​</a></h3><ol><li><code>useInitApp</code> → сначала задаёт <code>axios</code> baseURL и credentials. Если задан Query-параметр <code>?fake</code>, то baseURL <code>&#39;&#39;</code>, иначе указанный домен.</li><li><code>settingsStore.setMode</code> → устанавливает режим отображения всего приложения <code>button|embed</code> кнопкой или встраиваемым блоком.</li><li><code>settingsStore.getBaseDataProject</code> → получает брендовые цвета, стартовое сообщение, базовую галерею, frozen (заморожен ли проект). Если ответ возвращается 404 статус, то всё приложение скрывается и дальнейшие запросы не отправляются.</li><li>Auth → запрос данных пользователя, обновление токена через рефреш-токен или анонимная авторизация.</li><li><code>chatStore.fetchUserChats()</code> → запрос чатов пользователя.</li></ol><h3 id="сообщение-пользователя" tabindex="-1">Сообщение пользователя <a class="header-anchor" href="#сообщение-пользователя" aria-label="Permalink to &quot;Сообщение пользователя&quot;">​</a></h3><ol><li><code>ChatAction</code> / <code>EmptyChat</code> / <code>SuggestedOptions</code> → <code>chatStore.sendMessage</code>.</li><li>Thinking-состояние → ответ ассистента в <code>activeChat.messages</code>.</li><li>При наличии <code>dataObjectVisual</code> → <code>lastAiAnswer</code> → <code>ChatView</code> монтирует visual-компонент.</li></ol><h3 id="поиск-по-сообщениям" tabindex="-1">Поиск по сообщениям <a class="header-anchor" href="#поиск-по-сообщениям" aria-label="Permalink to &quot;Поиск по сообщениям&quot;">​</a></h3><ol><li>Сайдбар → <code>searchMessagesByContent</code>.</li><li>Клик по результату → <code>openChatAtMessage</code>.</li><li><code>highlightMessageId</code> в сторе + <code>ChatList</code> скроллит и включает <strong>локальную</strong> визуальную подсветку на 3 с.</li></ol><p>Подробности: <a href="./features/chat">Chat</a>.</p><h2 id="паттерны" tabindex="-1">Паттерны <a class="header-anchor" href="#паттерны" aria-label="Permalink to &quot;Паттерны&quot;">​</a></h2><h3 id="pinia" tabindex="-1">Pinia <a class="header-anchor" href="#pinia" aria-label="Permalink to &quot;Pinia&quot;">​</a></h3><ul><li>Имена getters: <code>get*</code>.</li><li>Actions вызывают services и мутируют state.</li><li>Feature-store не должен знать о DOM; UI-эффекты (скролл, класс подсветки) — в компонентах.</li></ul><h3 id="event-bus" tabindex="-1">Event bus <a class="header-anchor" href="#event-bus" aria-label="Permalink to &quot;Event bus&quot;">​</a></h3><p><code>shared/utils/eventBus.ts</code> (mitt):</p><ul><li><code>chat:send-message</code> — событие при отправке сообщения (закрытие сайдбара/поиска);</li><li><code>chat:clear-visual</code> — сброс visual-панели при logout и т.п.</li></ul><h3 id="именование-css-bem" tabindex="-1">Именование CSS (BEM) <a class="header-anchor" href="#именование-css-bem" aria-label="Permalink to &quot;Именование CSS (BEM)&quot;">​</a></h3><ul><li>Блок: <code>.gp-chat-list</code></li><li>Элемент: <code>.gp-chat-list__sentinel</code></li><li>Модификатор темы: <code>.gp-button_theme_white</code></li><li>Состояние: <code>.is-open</code>, <code>.is-highlighted</code></li></ul><p>Prop <code>modify</code> у shared-компонентов добавляет внешние классы без ломки базовых стилей.</p><h3 id="изоляция-на-хост-странице" tabindex="-1">Изоляция на хост-странице <a class="header-anchor" href="#изоляция-на-хост-странице" aria-label="Permalink to &quot;Изоляция на хост-странице&quot;">​</a></h3><ul><li>Корень <code>#gigaplan</code> / <code>.gigaplan</code></li><li>PostCSS <code>prefixwrap</code> в Vite</li><li>CSS инжектится в JS-бандл</li><li>В режиме <code>button</code> — высокий <code>z-index</code> (<code>total</code>) чтобы перекрывать другие библиотеки/блоки, а также lock scroll body хоста</li></ul><h2 id="связь-chatview-и-визуалов" tabindex="-1">Связь ChatView и визуалов <a class="header-anchor" href="#связь-chatview-и-визуалов" aria-label="Permalink to &quot;Связь ChatView и визуалов&quot;">​</a></h2><p><code>ChatView</code> смотрит на <code>chatStore.getLastAiAnswer</code> (<code>dataObjectVisual</code>) и выбирает компонент по ключу (<code>map</code>, <code>premises</code>, <code>images</code>, …). Таблица ключей — в <a href="/docs/features/visual-blocks/">Визуальных блоках</a>.</p>',33)])])}const b=t(i,[["render",c]]);export{p as __pageData,b as default};
